--[[
    VNDT Roll-a-Fisherman | Nebula v5 GitHub library
    ---------------------------------------------------------------------
    This is a direct Luau source translation from the supplied obfuscated
    program. Its original game/automation functions are retained. All original UI
    calls are translated to the GitHub VNDT UI library by an adapter.

    The original contained 566 VM function prototypes and 27,246 instructions.
    Here each function is real Luau code: there is no encrypted payload,
    bytecode table, decoder, VM interpreter, or dynamic opcode execution.

    Original local variable names and original high-level control flow were
    lost to virtualization. Register temporaries and basic-block jumps remain
    explicit. This is NOT equivalent to a hand-written source recovery.

    IMPORTANT: The VNDT UI library is requested from its owner GitHub repo.
    Review external code before running.
    Game behavior has not been tested in Roblox. Some original routines can
    fail when server/game structures change; this script does not fix those.

    EDIT CUSTOM.UI below to customize VNDT UI titles, theme, and URL.
    Other features: search labels and routines using the SYMBOL INDEX
    file shipped with this reconstruction.
--]]

local CUSTOM = {
    UI = {
        LibraryURL = "https://raw.githubusercontent.com/ejerzhome25/ZHM2/main/VNDT_UI_Library_Nebula.lua",
        Theme = "Midnight",
        ScriptName = "Roll-a-Fisherman",
        WindowTitle = "VNDT Nebula | Roll a Fisherman",
        HubName = "Automation Hub",
    },
    -- Direct wheel spin based on the working MomongaHub network path.
    AutoSpin = {
        DefaultInterval = 5,
        MinimumInterval = 1,
        MaximumInterval = 60,
    },
    -- Direct SellAll job, independent of Gold Rush.
    AutoSellAll = {
        DefaultInterval = 5,
        MinimumInterval = 1,
        MaximumInterval = 60,
        SellType = "Fish",
    },
    -- Original Auto Collect settings. Its UI and runtime callbacks are unchanged.
    Collect = {
        MinimumSeconds = 10,
        MaximumSeconds = 600,
        SliderStep = 10,
        DefaultSeconds = 60,
    },
}

--[[
    Nebula v5 UI compatibility layer for the original Roll-a-Fisherman application.
    IMPORTANT: The 566 recovered game / automation functions below are kept intact.
    This adapter translates the original AirFlow widget contract to the
    owner's VNDT_UI_Library_Nebula.lua (mobile + floating minimizer).

    Notes:
      * The original picture/card picker is now a VNDT rarity picker plus
        searchable multiple-selection list (same selected fisherman IDs).
      * The VNDT GitHub library does not contain AirFlow's config manager, so
        this adds optional local save/load if executor file APIs are present.
      * Auto Spin uses MomongaHub's direct WheelSpin remote (no events gate).
      * No feature success is asserted without testing in the live game.
]]
local function MakeVNDTAdapter(VNDT)
    assert(type(VNDT) == "table" and type(VNDT.CreateWindow) == "function",
        "Unable to load VNDT Nebula UI library from GitHub")

    local Adapter = { Flags = {}, Windows = {}, Version = "VNDT Nebula v5 compatibility" }
    local userInput = game:GetService("UserInputService")
    local HttpService = game:GetService("HttpService")
    local appName = "Roll-a-Fisherman"

    local function safeInvoke(fn, ...)
        if type(fn) ~= "function" then return end
        local ok, result = pcall(fn, ...)
        if not ok then warn("[VNDT callback] " .. tostring(result)) end
        return result
    end

    local function textOf(config, default)
        if type(config) == "table" then
            return tostring(config.Name or config.Text or default or "")
        end
        return tostring(config or default or "")
    end

    local function listOptions(data)
        local options, used = {}, {}
        if type(data) ~= "table" then return options end
        for _, value in ipairs(data) do
            local v = type(value) == "table" and (value.Name or value.Label or value.Value or value.Id) or value
            if v ~= nil and not used[tostring(v)] then
                used[tostring(v)] = true
                table.insert(options, tostring(v))
            end
        end
        if #options == 0 then
            for key, value in pairs(data) do
                if value == true and not used[tostring(key)] then
                    used[tostring(key)] = true
                    table.insert(options, tostring(key))
                end
            end
            table.sort(options)
        end
        return options
    end

    local function selectedMap(value)
        local result = {}
        if type(value) == "table" then
            for key, item in pairs(value) do
                if type(key) == "number" then
                    if type(item) == "string" or type(item) == "number" then
                        result[tostring(item)] = true
                    elseif type(item) == "table" and item.Name then
                        result[tostring(item.Name)] = true
                    end
                elseif item == true or type(item) == "string" then
                    result[tostring(key)] = true
                end
            end
        end
        return result
    end

    local function copyMap(map)
        local dest = {}
        for key, flag in pairs(map) do if flag then dest[key] = true end end
        return dest
    end

    local function register(config, widget)
        if type(config) == "table" and type(config.Flag) == "string" then
            Adapter.Flags[config.Flag] = widget
        end
        return widget
    end

    local function optionalDescription(tab, c)
        local desc = c.Desc or c.Description
        if type(desc) == "string" and desc ~= "" then
            tab:CreateLabel(desc)
        end
    end

    function Adapter:SetTheme(theme)
        -- "Midnight" from original AirFlow maps to VNDT's built-in dark theme.
        -- VNDT:SetTheme accepts a color palette table, not a theme name.
        if type(theme) == "table" and type(VNDT.SetTheme) == "function" then
            safeInvoke(function() VNDT:SetTheme(theme) end)
        end
    end
    function Adapter:MainCredit() end
    function Adapter:SetScriptName(name) appName = tostring(name or appName) end
    function Adapter:Notify(a, b, c)
        local config = type(a) == "table" and a or {
            Title = tostring(a or appName), Content = tostring(b or ""), Type = c
        }
        local target = self.Windows[#self.Windows]
        if target then
            safeInvoke(function()
                target.Real:Notify({
                    Title = config.Title or appName,
                    Content = config.Content or config.Description or "",
                    Duration = config.Duration or 4,
                    Type = config.Type
                })
            end)
        end
    end

    -- Direct Auto Spin using native VNDT widgets, with the same WheelSpin network call.
    -- Unlike the original wheel implementation, there is NO selected-event gate.
    local function installAutoSpin(realTab, window)
        if window.AutoSpinInstalled then return window.AutoSpinControl end
        window.AutoSpinInstalled = true

        local config = CUSTOM.AutoSpin
        local state = {
            Enabled = false,
            Interval = config.DefaultInterval,
            NextRun = 0,
            Busy = false,
            WorkerStarted = false,
            Remote = nil,
            Attempts = 0,
            Spins = 0,
            Refused = 0,
            Errors = 0,
            LastMessage = "Ready",
        }
        window.AutoSpin = state

        local status = realTab:CreateLabel("Auto Spin: OFF")
        local function showStatus()
            if not window.Alive then return end
            local mode = state.Enabled and "ON" or "OFF"
            local remain = math.max(0, state.NextRun - os.clock())
            local text = string.format("Auto Spin: %s | spins: %d | refused: %d | errors: %d",
                mode, state.Spins, state.Refused, state.Errors)
            if state.Enabled then
                text = text .. string.format(" | next: %.1fs", remain)
            end
            if state.LastMessage and state.LastMessage ~= "Ready" then
                text = text .. " | " .. tostring(state.LastMessage):sub(1, 72)
            end
            status:Set(text)
        end

        local function resolveSpinRemote()
            if state.Remote then return state.Remote end
            local replicated = game:GetService("ReplicatedStorage")
            local modules = replicated:FindFirstChild("Modules")
            local util = modules and modules:FindFirstChild("Util")
            local netModule = util and util:FindFirstChild("Net")
            if not netModule or not netModule:IsA("ModuleScript") then
                error("Waiting for Modules.Util.Net")
            end
            if not replicated:FindFirstChild("NetClient") then
                error("Waiting for NetClient")
            end
            local net = require(netModule)
            assert(net and type(net.Function) == "function", "Net:Function unavailable")
            local remote = net:Function("WheelSpin")
            assert(remote and type(remote.InvokeServer) == "function", "WheelSpin function unavailable")
            state.Remote = remote
            return remote
        end

        local function sendSpinRequest()
            if not window.Alive or state.Busy then return end
            state.Busy = true
            state.Attempts = state.Attempts + 1
            local ok, result = pcall(function()
                -- Exactly MomongaHub's wheel method: net:Function("WheelSpin"):InvokeServer()
                return resolveSpinRemote():InvokeServer()
            end)
            state.Busy = false
            if not window.Alive then return end
            if not ok then
                state.Errors = state.Errors + 1
                state.Remote = nil -- allow fresh resolution after network failures
                state.LastMessage = "Network error; retrying"
                warn("[VNDT Auto Spin] " .. tostring(result))
            elseif not result then
                state.Refused = state.Refused + 1
                state.LastMessage = "No spin result (possibly no spins left)"
            else
                state.Spins = state.Spins + 1
                state.LastMessage = "Last spin accepted"
            end
            showStatus()
        end

        local function startWorker()
            if state.WorkerStarted then return end
            state.WorkerStarted = true
            task.spawn(function()
                local ok, err = pcall(function()
                    while window.Alive do
                        if state.Enabled then
                            local now = os.clock()
                            if not state.Busy and now >= state.NextRun then
                                state.NextRun = now + state.Interval
                                task.spawn(sendSpinRequest)
                            end
                        end
                        task.wait(0.2)
                    end
                end)
                state.WorkerStarted = false
                if not ok then
                    warn("[VNDT Auto Spin worker] " .. tostring(err))
                    if state.Enabled and window.Alive then
                        task.wait(1)
                        startWorker()
                    end
                end
            end)
        end

        local function enableAutoSpin(value)
            state.Enabled = value == true
            if state.Enabled then
                -- Start immediately, including when an already-running worker is asleep.
                state.NextRun = os.clock() + state.Interval
                startWorker()
                task.spawn(sendSpinRequest)
            else
                state.NextRun = 0
            end
            showStatus()
        end

        local toggle = realTab:CreateToggle({
            Name = "Auto Spin",
            Description = "Spin continuously every 5 seconds by default. No event selection required.",
            Default = false,
            Callback = enableAutoSpin,
        })
        -- Nebula v5 Toggle:Set invokes Callback itself (including config restore).
        -- Do not call enableAutoSpin twice on a programmatic Set.
        window.AutoSpinControl = register({Flag = "RAFAutoWheel"}, toggle)

        local slider = realTab:CreateSlider({
            Name = "Spin Interval (seconds)",
            Min = config.MinimumInterval,
            Max = config.MaximumInterval,
            Increment = 1,
            Default = config.DefaultInterval,
            Callback = function(value)
                state.Interval = math.clamp(math.floor(tonumber(value) or config.DefaultInterval),
                    config.MinimumInterval, config.MaximumInterval)
                if state.Enabled then state.NextRun = os.clock() + state.Interval end
                showStatus()
            end,
        })
        -- Nebula v5 Slider:Set already fires its Callback and updates Interval.
        register({Flag = "VNDT_AutoSpinInterval"}, slider)

        realTab:CreateButton({
            Name = "Spin Now",
            Description = "Try a single WheelSpin now, even if Auto Spin is off.",
            Callback = function() task.spawn(sendSpinRequest) end,
        })
        realTab:CreateLabel("A completed request still requires available wheel spins on the server.")
        task.spawn(function()
            while window.Alive do
                if state.Enabled then showStatus() end
                task.wait(0.5)
            end
        end)
        return window.AutoSpinControl
    end

    -- Independent, continuously scheduled SellAll("Fish") requests.
    -- The native Roll-a-Fisherman selling routines are untouched.
    local function installAutoSellAll(realTab, window)
        if window.AutoSellInstalled then return end
        window.AutoSellInstalled = true

        local config = CUSTOM.AutoSellAll
        local state = {
            Enabled = false,
            Interval = config.DefaultInterval,
            Remote = nil,
            Net = nil,
            Busy = false,
            Sent = 0,
            Errors = 0,
            NextRun = 0,
            WorkerStarted = false,
            LastError = nil,
        }
        window.AutoSellAll = state
        realTab:CreateSection("Auto Sell All")
        local status = realTab:CreateLabel("Auto Sell All: OFF")

        local function showStatus()
            if not window.Alive then return end
            if not state.Enabled and not state.Busy then
                status:Set("Auto Sell All: OFF | requests sent: " .. state.Sent)
            elseif state.LastError then
                status:Set("Auto Sell All: " .. tostring(state.LastError):sub(1, 95))
            else
                local remain = math.max(0, state.NextRun - os.clock())
                status:Set(string.format("Auto Sell All: %s | requests: %d | errors: %d | next: %.1fs",
                    state.Enabled and "ON" or "OFF", state.Sent, state.Errors, remain))
            end
        end

        local function resolveRemote()
            if state.Remote then return state.Remote end
            local replicated = game:GetService("ReplicatedStorage")
            local modules = replicated:FindFirstChild("Modules")
            local util = modules and modules:FindFirstChild("Util")
            local netModule = util and util:FindFirstChild("Net")
            if not netModule or not netModule:IsA("ModuleScript") then
                error("Waiting for Modules.Util.Net")
            end
            -- Momonga's original bootstrap waits for NetClient to load before getting remotes.
            -- A missing client means we retry instead of caching a half-initialized remote.
            if not replicated:FindFirstChild("NetClient") then
                error("Waiting for NetClient")
            end
            local net = require(netModule)
            assert(net and type(net.Event) == "function", "Game Net module unavailable")
            local remote = net:Event("SellAll")
            assert(remote and type(remote.FireServer) == "function", "SellAll event unavailable")
            state.Remote = remote
            return remote
        end

        local function sendSellRequest()
            if not window.Alive or state.Busy then return end
            state.Busy = true
            local ok, err = pcall(function()
                resolveRemote():FireServer(config.SellType)
            end)
            state.Busy = false
            if ok then
                state.Sent = state.Sent + 1
                state.LastError = nil
            else
                state.Errors = state.Errors + 1
                state.Remote = nil
                state.LastError = tostring(err)
                warn("[VNDT Auto Sell All] " .. state.LastError)
            end
            showStatus()
        end

        local function startWorker()
            if state.WorkerStarted then return end
            state.WorkerStarted = true
            task.spawn(function()
                -- A guarded worker continues scheduling after individual failed requests.
                -- Each interval is handled once; it never spams multiple simultaneous sales.
                local ok, err = pcall(function()
                    while window.Alive do
                        if state.Enabled then
                            local now = os.clock()
                            if not state.Busy and now >= state.NextRun then
                                state.NextRun = now + state.Interval
                                task.spawn(sendSellRequest)
                            end
                            -- Keep the countdown visible between sales.
                            if not state.LastError then showStatus() end
                        end
                        task.wait(0.2)
                    end
                end)
                state.WorkerStarted = false
                if not ok then
                    state.LastError = "worker error: " .. tostring(err)
                    warn("[VNDT Auto Sell All] " .. state.LastError)
                    showStatus()
                    if window.Alive and state.Enabled then
                        task.wait(1)
                        startWorker() -- Self-heal if the worker itself unexpectedly stops.
                    end
                end
            end)
        end

        local function enableAutoSell(value)
            state.Enabled = value == true
            state.LastError = nil
            if state.Enabled then
                state.NextRun = 0 -- first request immediately; keep repeating afterwards
                startWorker()
            end
            showStatus()
        end

        local toggle = realTab:CreateToggle({
            Name = "Auto Sell All",
            Description = "Sell all fish automatically using the game's SellAll event and sell filters.",
            Default = false,
            Callback = enableAutoSell,
        })
        -- Nebula v5 Toggle:Set fires Callback for user and config changes.
        register({Flag = "VNDT_AutoSellAll"}, toggle)

        local slider = realTab:CreateSlider({
            Name = "Sell Interval (seconds)",
            Min = config.MinimumInterval,
            Max = config.MaximumInterval,
            Default = config.DefaultInterval,
            Increment = 1,
            Callback = function(seconds)
                state.Interval = math.clamp(math.floor(tonumber(seconds) or config.DefaultInterval),
                    config.MinimumInterval, config.MaximumInterval)
                if state.Enabled then state.NextRun = os.clock() + state.Interval end
                showStatus()
            end,
        })
        -- Nebula v5 Slider:Set already invokes the callback.
        register({Flag = "VNDT_AutoSellInterval"}, slider)

        realTab:CreateButton({
            Name = "Sell All Now",
            Description = "Send one SellAll('Fish') request even when Auto Sell All is off.",
            Callback = sendSellRequest,
        })
        realTab:CreateLabel("Game sell filters apply. 'Requests' counts calls sent, not confirmed fish sold.")
    end

    function Adapter:CreateWindow(config)
        config = config or {}
        local size = config.Size
        local requestedWidth = size and size.X and size.X.Offset or 650
        local requestedHeight = size and size.Y and size.Y.Offset or 450
        local real = VNDT:CreateWindow({
            Name = tostring(config.Name or appName),
            Subtitle = tostring(config.Subtitle or "VNDT HUB"),
            Width = math.clamp(requestedWidth, 500, 710),
            Height = math.clamp(requestedHeight, 360, 500),
            MobileWidth = 490,
            MobileHeight = 350,
        })
        local window = {Real = real, Flags = Adapter.Flags, Tabs = {}, Alive = true,
            Key = tostring(config.ToggleUIKeybind or "RightControl")}
        table.insert(self.Windows, window)

        -- Create the primary controls directly with Nebula v5's API.
        -- The legacy wheel toggle is later mapped to this same VNDT control,
        -- so saved configs and Stop All continue to work without duplicate UI.
        local spinTab = real:CreateTab("Auto Spin")
        spinTab:CreateSection("Wheel automation")
        installAutoSpin(spinTab, window)

        function window:SetKeybind(key)
            if typeof(key) == "EnumItem" then key = key.Name end
            key = tostring(key or "RightControl")
            if Enum.KeyCode[key] then self.Key = key end
        end
        function window:SetVisible(isVisible)
            real:SetVisible(isVisible)
        end
        function window:Destroy()
            if not self.Alive then return end
            self.Alive = false
            if self.KeyConnection then self.KeyConnection:Disconnect() end
            real:Destroy()
        end
        -- Nebula's X button calls Gui:Destroy() directly: stop workers on close too.
        real.Gui.Destroying:Connect(function()
            window.Alive = false
            if window.KeyConnection then window.KeyConnection:Disconnect() end
        end)
        function window:Notify(config)
            return Adapter:Notify(config)
        end
        window.KeyConnection = userInput.InputBegan:Connect(function(input, processed)
            if processed or not window.Alive or userInput:GetFocusedTextBox() then return end
            if input.KeyCode.Name == window.Key then
                real:SetVisible(not real.Gui.Enabled)
            end
        end)

        function window:CreateTab(configTab)
            local realTab = real:CreateTab(textOf(configTab, "Tab"))
            local tab = {Real = realTab, Window = self}
            table.insert(self.Tabs, tab)

            function tab:CreateSection(configSection)
                if textOf(configSection, "Section") == "Wheel" then
                    tab.HideLegacyWheelStatus = true
                    return nil -- Wheel controls now live in the native VNDT Auto Spin tab.
                end
                return realTab:CreateSection(textOf(configSection, "Section"))
            end

            function tab:CreateLabel(configLabel)
                local c = type(configLabel) == "table" and configLabel or {Text = configLabel}
                if tab.HideLegacyWheelStatus and c.Text == "Off" and type(c.Update) == "function" then
                    -- Legacy label reports the old event-limited wheel worker, now inactive.
                    return {Set = function() end, Get = function() return "" end}
                end
                local label = realTab:CreateLabel(tostring(c.Text or c.Name or ""))
                if type(c.Update) == "function" then
                    task.spawn(function()
                        while window.Alive do
                            local updated = safeInvoke(c.Update)
                            if updated ~= nil then label:Set(tostring(updated)) end
                            task.wait(math.max(0.25, tonumber(c.UpdateRate) or 1))
                        end
                    end)
                end
                return register(c, label)
            end

            function tab:CreateButton(configButton)
                local c = type(configButton) == "table" and configButton or {Name = configButton}
                return realTab:CreateButton({
                    Name = textOf(c, "Button"), Description = c.Desc or c.Description,
                    Callback = function() safeInvoke(c.Callback) end,
                })
            end

            function tab:CreateToggle(configToggle)
                local c = configToggle or {}
                if c.Flag == "RAFAutoWheel" then
                    -- Reference the real VNDT Auto Spin widget on the dedicated tab.
                    return window.AutoSpinControl
                end
                if c.Flag == "RAFWheelSkip" then
                    -- Momonga's direct spinner does not use experimental WheelSkip.
                    local ignored = {Set = function() end, Get = function() return false end}
                    return register(c, ignored)
                end
                local control = realTab:CreateToggle({
                    Name = textOf(c, "Toggle"), Description = c.Desc or c.Description,
                    Default = c.Default == true,
                    Callback = function(value) safeInvoke(c.Callback, value == true) end,
                })
                return register(c, control)
            end

            function tab:CreateSlider(configSlider)
                local c = configSlider or {}
                optionalDescription(realTab, c)
                local control = realTab:CreateSlider({
                    Name = textOf(c, "Slider") .. tostring(c.Suffix or ""),
                    Min = c.Min or 0,
                    Max = c.Max or 100,
                    Default = c.Default or c.Min or 0,
                    Increment = tonumber(c.Step) or 1,
                    Callback = function(value)
                        local step = tonumber(c.Step) or 1
                        if step > 0 then
                            value = math.floor(value / step + 0.5) * step
                        end
                        safeInvoke(c.Callback, value)
                    end,
                })
                return register(c, control)
            end

            function tab:CreateDropdown(configDropdown)
                local c = configDropdown or {}
                if c.Flag == "RAFWheelEvents" then
                    -- Legacy event selection does not apply to continuous Auto Spin.
                    local ignored = {Set = function() end, Get = function() return {} end}
                    return register(c, ignored)
                end
                local options = listOptions(c.Options)
                optionalDescription(realTab, c)
                if c.Multi == true then
                    local chosen = selectedMap(c.Default or {})
                    local control = realTab:CreateMultiDropdown({
                        Name = textOf(c, "Multi Select"),
                        Options = options, Selected = chosen, Searchable = true,
                        Callback = function(_, _, selected)
                            chosen = copyMap(selected)
                            safeInvoke(c.Callback, copyMap(chosen))
                        end
                    })
                    local originalSetOptions = control.SetOptions
                    function control:Set(newSelection)
                        chosen = selectedMap(newSelection)
                        self:SetSelected(chosen, false)
                        safeInvoke(c.Callback, copyMap(chosen))
                    end
                    function control:Get() return copyMap(chosen) end
                    function control:Refresh(newOptions, fireCallback)
                        if type(newOptions) == "table" then
                            options = listOptions(newOptions)
                            originalSetOptions(self, options)
                        end
                        if fireCallback then safeInvoke(c.Callback, copyMap(chosen)) end
                    end
                    return register(c, control)
                else
                    local control = realTab:CreateDropdown({
                        Name = textOf(c, "Dropdown"), Options = options,
                        Default = c.Default or options[1],
                        Callback = function(value) safeInvoke(c.Callback, value) end,
                    })
                    local origSet = control.Set
                    function control:Set(value)
                        origSet(self, value, true)
                    end
                    return register(c, control)
                end
            end

            function tab:CreateInput(configInput)
                local c = configInput or {}
                optionalDescription(realTab, c)
                return register(c, realTab:CreateInput({
                    Name = textOf(c, "Input"), Default = c.Default or "",
                    Placeholder = c.Placeholder or "Enter text",
                    Callback = function(value, enter) safeInvoke(c.Callback, value, enter) end,
                }))
            end

            function tab:CreateKeybind(configKeybind)
                local c = configKeybind or {}
                local current = tostring(c.Default or "RightControl")
                local input = realTab:CreateInput({
                    Name = textOf(c, "Toggle UI Key"),
                    Default = current, Placeholder = "e.g. RightControl",
                    Callback = function(value)
                        value = tostring(value)
                        if Enum.KeyCode[value] then
                            current = value
                            window:SetKeybind(value)
                            safeInvoke(c.OnChanged or c.Callback, value)
                        else
                            input:Set(current)
                        end
                    end,
                })
                local handle = {}
                function handle:Get() return current end
                function handle:Set(value)
                    if typeof(value) == "EnumItem" then value = value.Name end
                    value = tostring(value)
                    if Enum.KeyCode[value] then
                        current = value
                        window:SetKeybind(value)
                        input:Set(value)
                        safeInvoke(c.OnChanged or c.Callback, value)
                    end
                end
                return register(c, handle)
            end

            function tab:CreateFilteredCardGrid(configGrid)
                local c = configGrid or {}
                realTab:CreateSection(textOf(c, "Choose fishermen"))
                optionalDescription(realTab, c)

                -- The Rarity dropdown now has a genuine, selectable NONE option.
                -- Choosing it also clears ALL selected fishermen, allowing roll only.
                local NONE = "Nothing Selected"
                local groups = c.Groups or {}
                local labels = {NONE}
                local entries = {[NONE] = {}}
                for i, group in ipairs(groups) do
                    local label = tostring(group.Label or ("Rarity " .. tostring(i)))
                    if label ~= NONE then
                        table.insert(labels, label)
                        entries[label] = listOptions(group.Items)
                    end
                end
                local checked = selectedMap(c.Default or {})
                local function groupForSelection(selection)
                    for _, label in ipairs(labels) do
                        if label ~= NONE then
                            for _, option in ipairs(entries[label] or {}) do
                                if selection[option] then return label end
                            end
                        end
                    end
                    return NONE
                end
                local active = groupForSelection(checked)
                local picker, rarityPicker
                local function send()
                    safeInvoke(c.Callback, copyMap(checked))
                end
                local function visibleSelections()
                    local result = {}
                    for _, option in ipairs(entries[active] or {}) do
                        if checked[option] then result[option] = true end
                    end
                    return result
                end
                local function applyToPicker()
                    if not picker then return end
                    picker:SetOptions(entries[active] or {})
                    picker:SetSelected(visibleSelections(), false)
                end
                rarityPicker = realTab:CreateDropdown({
                    Name = c.FilterName or "Rarity",
                    Options = labels,
                    Default = active,
                    Placeholder = NONE,
                    Callback = function(value)
                        if value == NONE then
                            active = NONE
                            checked = {}
                            applyToPicker()
                            send() -- Tell the existing automation to stop filtering by fisherman.
                        elseif entries[value] then
                            active = value
                            applyToPicker()
                        end
                    end,
                })
                picker = realTab:CreateMultiDropdown({
                    Name = c.Name or "Fishermen", Options = entries[active] or {},
                    Selected = visibleSelections(), Searchable = true,
                    Placeholder = NONE,
                    Callback = function(option, enabled)
                        if option ~= nil and active ~= NONE then
                            checked[option] = enabled and true or nil
                            send()
                        end
                    end,
                })
                local handle = {}
                function handle:Get() return copyMap(checked) end
                function handle:Set(value)
                    checked = selectedMap(value)
                    -- Keep the rarity filter and selection consistent when
                    -- a saved configuration updates the selected fishermen.
                    local matched = false
                    for _, option in ipairs(entries[active] or {}) do
                        if checked[option] then matched = true; break end
                    end
                    if not matched then active = groupForSelection(checked) end
                    if rarityPicker then rarityPicker:Set(active, false) end
                    applyToPicker()
                    send()
                end
                function handle:SelectAll()
                    if active == NONE then return end
                    for _, option in ipairs(entries[active] or {}) do checked[option] = true end
                    applyToPicker()
                    send()
                end
                function handle:DeselectAll()
                    checked = {}
                    active = NONE
                    if rarityPicker then rarityPicker:Set(NONE, false) end
                    applyToPicker()
                    send()
                end
                function handle:Refresh(newGroups, fireCallback)
                    if type(newGroups) == "table" then
                        groups = newGroups
                        labels, entries = {NONE}, {[NONE] = {}}
                        for i, group in ipairs(groups) do
                            local label = tostring(group.Label or ("Rarity " .. i))
                            if label ~= NONE then
                                table.insert(labels, label)
                                entries[label] = listOptions(group.Items)
                            end
                        end
                        if not entries[active] then active = NONE end
                        if rarityPicker then
                            rarityPicker:SetOptions(labels)
                            rarityPicker:Set(active, false)
                        end
                        applyToPicker()
                    end
                    if fireCallback then send() end
                end
                return register(c, handle)
            end

            function tab:CreateConfigManager(configManager)
                realTab:CreateSection(textOf(configManager, "Configs"))
                local folder = "VNDT_RollAFisherman"
                local path = folder .. "/settings.json"
                local function canSave()
                    return type(writefile) == "function" and type(readfile) == "function"
                        and type(isfile) == "function"
                end
                local function saveConfig()
                    if not canSave() then
                        Adapter:Notify("Configs", "Your executor does not support file storage", "Warning")
                        return
                    end
                    local saved = {}
                    for flag, widget in pairs(Adapter.Flags) do
                        local ok, value = pcall(function() return widget:Get() end)
                        if ok and (type(value) == "boolean" or type(value) == "string"
                             or type(value) == "number" or type(value) == "table") then
                            saved[flag] = value
                        end
                    end
                    local ok, err = pcall(function()
                        if type(makefolder) == "function" then
                            if type(isfolder) ~= "function" or not isfolder(folder) then makefolder(folder) end
                        end
                        writefile(path, HttpService:JSONEncode(saved))
                    end)
                    Adapter:Notify("Configs", ok and "Saved your VNDT settings" or tostring(err), ok and "Success" or "Error")
                end
                local function loadConfig(silent)
                    if not canSave() or not isfile(path) then
                        if not silent then Adapter:Notify("Configs", "No saved configuration found", "Warning") end
                        return
                    end
                    local ok, err = pcall(function()
                        local saved = HttpService:JSONDecode(readfile(path))
                        if type(saved) ~= "table" then return end
                        -- Migrate previously saved sell settings after the UI rename.
                        if saved.VNDT_AutoSellAll == nil then
                            saved.VNDT_AutoSellAll = saved.VNDT_MomongaAutoSellAll
                        end
                        if saved.VNDT_AutoSellInterval == nil then
                            saved.VNDT_AutoSellInterval = saved.VNDT_MomongaSellInterval
                        end
                        for flag, value in pairs(saved) do
                            local widget = Adapter.Flags[flag]
                            if widget then safeInvoke(function() widget:Set(value) end) end
                        end
                    end)
                    if not silent then
                        Adapter:Notify("Configs", ok and "Loaded your saved VNDT settings" or tostring(err), ok and "Success" or "Error")
                    end
                end
                realTab:CreateButton({Name = "Save Config", Callback = saveConfig})
                realTab:CreateButton({Name = "Load Config", Callback = function() loadConfig(false) end})
                -- Original UI was configured with AutoLoad = true.
                task.defer(function() if window.Alive then loadConfig(true) end end)
            end
            if textOf(configTab, "Tab") == "Fishing" then
                installAutoSellAll(realTab, window)
            end
            return tab
        end
        return window
    end
    return Adapter
end

local GLOBALS = (getfenv and getfenv(0)) or _G
local UNPACK = table.unpack or unpack
local FUNCTIONS = {}  -- Native Luau functions, not opcode handlers.

local function captureReturns(...)
    return select("#", ...), {...}
end
local function openCapturedRegister(openCells, registers, slot)
    local cell = openCells[slot]
    if not cell then
        cell = { Owner = registers, Index = slot }
        openCells[slot] = cell
    end
    return cell
end
local function closeCapturedRegisters(openCells, registers, first)
    for slot, cell in pairs(openCells) do
        if slot >= first then
            cell.Owner = {[cell.Index] = registers[slot]}
            openCells[slot] = nil
        end
    end
end

